import{_ as i,C as a,c as s,o as l,aj as h,j as t,G as o,a as c,w as d}from"./chunks/framework.Bfdr4H5E.js";const p="/sk/images/Kite-trading-terminal.webp",u="/sk/images/Watchlist-bid-offer.webp",v=JSON.parse('{"title":"Journey of a Share","description":"","frontmatter":{"outline":"deep","prev":{"text":"Why Should You Invest ?","link":"/trading-with-pav/why-should-you-invest"},"next":{"text":"Market Segments","link":"/trading-with-pav/market-segments"}},"headers":[],"relativePath":"trading-with-pav/journey-of-a-share.md","filePath":"trading-with-pav/journey-of-a-share.md"}'),g={name:"trading-with-pav/journey-of-a-share.md"};function m(k,e,f,b,y,w){const r=a("GraphComment"),n=a("ClientOnly");return l(),s("div",null,[e[0]||(e[0]=h('<h1 id="journey-of-a-share" tabindex="-1">Journey of a Share <a class="header-anchor" href="#journey-of-a-share" aria-label="Permalink to &quot;Journey of a Share&quot;">​</a></h1><p>In this article, we will learn about the different financial intermediaries in Indian Stock Market and how they interact to ensure your transactions go through seamlessly.</p><div class="info custom-block"><p class="custom-block-title">Table of Content</p><nav class="table-of-contents"><ul><li><a href="#things-to-know-before-your-first-stock-market-transaction">Things to Know Before Your First Stock Market Transaction</a></li><li><a href="#know-the-ecosystem">Know the Ecosystem</a><ul><li><a href="#journey-of-a-trade">Journey of a Trade.</a></li></ul></li><li><a href="#the-stock-market-participants">The Stock Market Participants</a></li><li><a href="#video">Video</a></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="things-to-know-before-your-first-stock-market-transaction" tabindex="-1">Things to Know Before Your First Stock Market Transaction <a class="header-anchor" href="#things-to-know-before-your-first-stock-market-transaction" aria-label="Permalink to &quot;Things to Know Before Your First Stock Market Transaction&quot;">​</a></h2><p>A Vegetable and Fruits vendor enables us to buy an apple without interacting with the farmer. In other words, there needs to be a market for us to buy the fruits. This Market called as a “Vegetable mandi” where farmers come from nearby areas to sell their produce and government agents, private players, and individuals wholesale buyers come here to buy vegetables.</p><p>This is similar to a Stock Exchange, there are two main stock exchanges in India that make up the stock markets. They are the Bombay Stock Exchange (BSE) and the National Stock Exchange (NSE). Here buyers and sellers can exchange shares via a bidding offer process.</p><h2 id="know-the-ecosystem" tabindex="-1">Know the Ecosystem <a class="header-anchor" href="#know-the-ecosystem" aria-label="Permalink to &quot;Know the Ecosystem&quot;">​</a></h2><p>Before we understand how this works lets place an order on a broker Terminal so that we can understand the journey of this single trade.</p><p><img src="'+p+'" alt="Kite-trading-terminal"><em>Kite-trading-terminal.</em></p><p>Trading Terminal</p><p>The above image is Zerodha’s terminal called Kite web platform, on this image there is a watchlist on left and chart on right.</p><p><img src="'+u+'" alt="Watchlist-bid-offer."><em>bid-offer.</em></p><p>Market Depth</p><p>The above image shows Last Traded Price (LTP) @2427.30. On the right we can see Bid Column which is basically all the people who placed orders to buy this stock at certain prices usually this is always lower than the LTP and then we have Offers on right where people have placed orders to sell this stock which is usually above the current LTP.</p><p>This is how price discovery happens people are bidding and offering stock at different prices and where there’s more pressure and trades take place, that’s how prices move in simple demand and supply, which can be seen in <strong>market depth</strong>.</p><h3 id="journey-of-a-trade" tabindex="-1">Journey of a Trade. <a class="header-anchor" href="#journey-of-a-trade" aria-label="Permalink to &quot;Journey of a Trade.&quot;">​</a></h3><p>Let’s assume we buy 10 shares of Reliance and see the journey of this trade one by one. For this shares to be credited to our Demat account a lot of market intermediaries are involved so let’s try to understand how that works.</p><h4 id="broker" tabindex="-1">Broker <a class="header-anchor" href="#broker" aria-label="Permalink to &quot;Broker&quot;">​</a></h4><p>We placed our order of Reliance using Zerodha’s kite web platform.<br> Some of the top brokers in india are as follows</p><ul><li><a href="https://zerodha.com/?c=LR6790&amp;s=CONSOLE" target="_blank" rel="noreferrer">Zerodha</a></li><li>Upstox</li><li><a href="https://open-account.fyers.in/?id=XY00224" target="_blank" rel="noreferrer">FYERS</a></li><li><a href="https://invite.dhan.co/?invite=KJXFR31859" target="_blank" rel="noreferrer">Dhan</a></li><li>Sharekhan</li><li>Angel Broking</li><li>India Infoline (IIFL)</li><li>Motilal Oswal</li></ul><h5 id="stock-broker-functions-are-as-follow" tabindex="-1">Stock broker functions are as follow <a class="header-anchor" href="#stock-broker-functions-are-as-follow" aria-label="Permalink to &quot;Stock broker functions are as follow&quot;">​</a></h5><ol><li>A Stock broker is a corporate entity, registered as a trading member with the <strong>Stock Exchange</strong>.</li><li>Holds a stockbroking license.</li><li>Follow <strong>SEBI</strong> prescribed guidelines.</li><li>Let’s the investor buy/sell securities.</li><li>Orders can be placed online via web or mobile app.</li></ol><h5 id="services-given-by-a-stockbroker" tabindex="-1">Services Given by a Stockbroker <a class="header-anchor" href="#services-given-by-a-stockbroker" aria-label="Permalink to &quot;Services Given by a Stockbroker&quot;">​</a></h5><ol><li><strong>Access to markets</strong>. (letting us transact)</li><li><strong>Provides margins for trading</strong>.</li><li><strong>Dealing support for call and trade</strong>.</li><li><strong>Issue contract notes for the transactions.</strong></li><li><strong>Facilitate the fund transfer between your trading and bank account.</strong></li><li><strong>Provide you with a back-office logins to see the summary of account.</strong></li><li><strong>Brokerage Charge</strong> (a broking fee also called brokerage for the services provided, its upto you as a client to figure out and get the right balance between the services you want to get and the brokrage charge you want to pay coz it varies form broker to broker).</li></ol><p>After the broker the order is relayed to <strong>Stock Exchange</strong>.</p><h4 id="stock-exchange" tabindex="-1">Stock Exchange <a class="header-anchor" href="#stock-exchange" aria-label="Permalink to &quot;Stock Exchange&quot;">​</a></h4><p>There are two main stock exchanges in India that make up the stock markets.</p><ol><li>The <strong><a href="https://en.wikipedia.org/wiki/National_Stock_Exchange_of_India" title="National Stock Exchange of India Limited, also known as the National Stock Exchange (NSE), is an Indian stock exchange based in Mumbai. It is the 5th largest stock exchange in the world by total market capitalization, exceeding $5 trillion in May 2024." target="_blank" rel="noreferrer">National Stock Exchange (NSE)</a></strong> and</li><li>The <strong><a href="https://en.wikipedia.org/wiki/Bombay_Stock_Exchange" title="BSE Limited, also known as the Bombay Stock Exchange (BSE), is an Indian stock exchange based in Mumbai. Established in 1875, it is the oldest stock exchange in Asia, and also the tenth oldest in the world. It is the 6th largest stock exchange in the world by total market capitalization, exceeding $5 trillion in May 2024." target="_blank" rel="noreferrer">Bombay Stock Exchange (BSE)</a></strong>.</li></ol><p>Besides these two exchanges, there are many other regional stock exchanges like Bangalore Stock Exchange, Madras Stock Exchange that are more or less getting phased out and don’t really play any meaningful role anymore.</p><p>The <strong>buy and sell orders are placed and matched</strong> in the exchange, hence the name <strong>Stock Exchange</strong>. So bids flow in and offers flow in as explaned above in market depth. When we placed our order to buy Reliance a coresponding offer was matched and trade took place thats how we were able to buy those shares for Reliance.</p><p>So after the trade is exceuted it will now move to <strong>Clearing Corporation</strong> where the trade will actually get cleared.</p><h4 id="clearing-corporation" tabindex="-1">Clearing Corporation <a class="header-anchor" href="#clearing-corporation" aria-label="Permalink to &quot;Clearing Corporation&quot;">​</a></h4><p>There are 2 Clearing Corporation in India</p><ol><li><strong>NSCCL (National Securities Clearing Corporation Limited)</strong> a wholly owned subsidiary of NSE</li><li><strong>ICCL (Indian Clearing Corporation Limited)</strong> a wholly owned subsidiary of BSE</li></ol><p>The Functions of Clearing Corporation is to make sure that after transaction takes place it actually goes through, which means that the account which needs to pay the money that is debited and shares gets credited to the account which is purchased the shares. So neither of the party (buyer or seller) default on transaction that took place.</p><p>In Summery we placed the order with the broker it was matched at the exchange and clearing corporation ensures that transaction takes place. Once the Clearing Corporation clears those shares the next step is the <strong>Depository</strong>.</p><h4 id="depository" tabindex="-1">Depository <a class="header-anchor" href="#depository" aria-label="Permalink to &quot;Depository&quot;">​</a></h4><p>The Depository is like a Digital Locker storing all of our shares Digitally. The broker and the Depository are deeply integrated which means when we bought those Reliance shares once they are credited to our account we will be able to see it on our broker terminal.<br> There are 2 Depository in India</p><ol><li><strong>NSDL (National Securities Depository Limited)</strong> a wholly owned subsidiary of NSE.</li><li><strong>CDSL (Central Depository Services Limited)</strong> a wholly owned subsidiary of BSE.</li></ol><p>The broker and the depository are interlinked to each other via a mechanism called <strong>Depository Participants</strong>, If you want to understand more on Depository Participants check this <a href="https://zerodha.com/varsity/chapter/financial-intermediaries/" target="_blank" rel="noreferrer">link</a>.</p><p>So the Depository is the last step for the transaction of Reliance share we bought. This is where the shares will get credited and be reflected in our account (our broker terminal).</p><p>Now appart form this journey there are two other participants we need to know about in the ecosystem that’s the <strong>Bank</strong> and <strong>SEBI</strong>.</p><h4 id="bank" tabindex="-1">Bank <a class="header-anchor" href="#bank" aria-label="Permalink to &quot;Bank&quot;">​</a></h4><p>Banks play a very straightforward role in the market ecosystem. They help in facilitating the fund transfer from your bank account to your trading account and vice versa. You cannot transfer money from a bank account that is not in your name.</p><p>You can link multiple bank accounts to your trading through which you can transfer funds and trade. On Zerodha, you can add 1 primary bank account and up to 2 secondary bank accounts. You can use all the bank accounts to add funds, but withdrawals are only processed to the primary bank account.</p><p>Also, dividend payments, money from buybacks will be sent to the primary bank account. The primary bank account is connected to your trading account and with the Depository.</p><h4 id="sebi-securities-and-exchange-board-of-india" tabindex="-1">SEBI (Securities and Exchange Board of India) <a class="header-anchor" href="#sebi-securities-and-exchange-board-of-india" aria-label="Permalink to &quot;SEBI (Securities and Exchange Board of India)&quot;">​</a></h4><p>SEBI is the financial regulator for the entire market which means all the participants from the broker,exchange,clearing corporation,depository are regulated by SEBI.</p><p>The objective of SEBI is to promote the development of stock exchanges, protect the interest of retail investors, and regulate market participants and financial intermediaries’ activities. In general, SEBI ensures the following:</p><ol><li><strong>The stock exchanges (NSE and BSE) conducts its business fairly</strong></li><li><strong>Stockbrokers and sub-brokers conduct their business fairly</strong></li><li><strong>Participants don’t get involved in unfair practices</strong></li><li><strong>Corporate’s don’t use the markets to unduly benefit themselves (Example – Satyam Computers)</strong></li><li><strong>Small retail investors interests are protected</strong></li><li><strong>Large investors with huge cash pile should not manipulate the markets</strong></li><li><strong>Overall development of markets</strong></li></ol><p>All the rules and regulation are drafted and enforced by SEBI. You can the Guidelines around the market in this link on SEBI’s website. Banks on the other hand are regulated by RBI Reserve bank of India and not SEBI. The rules prescribed by the SEBI safeguard the investor and the trader.</p><h2 id="the-stock-market-participants" tabindex="-1">The Stock Market Participants <a class="header-anchor" href="#the-stock-market-participants" aria-label="Permalink to &quot;The Stock Market Participants&quot;">​</a></h2><p>The stock market attracts individuals and corporations from diverse backgrounds. Anyone who transacts in the stock market is called a <strong>market participant</strong>. The market participant can be classified into various categories. Some of the categories of market participants are as follows:</p><ol><li><strong>Domestic Retail Participants</strong> – These are people like you and me transacting in markets.</li><li><strong>Domestic Institutions</strong> – These are large corporate entities based in India. A classic example would be the LIC of India, etc.</li><li><strong>Domestic Asset Management Companies</strong> (AMC) – Typical participants in this category would be the <strong>Mutual Fund companies</strong> such as SBI Mutual Fund, DSP Black Rock, Fidelity Investments, HDFC AMC, etc.</li><li><strong>Foreign Institutional Investors</strong> (Non-Indian corporate entities) – These could be foreign asset management companies,<strong>Foreign Banks</strong>, <strong>Hedge funds</strong>, and other investors.</li><li><strong>NRI’s and OCI</strong> – These are people of Indian origin but based outside India.</li></ol><p>Now, irrespective of the category of market participant, everyone’s agenda is the same – to make profitable transactions. More bluntly put – to make money.</p><p>When money is involved, human emotions in the form of greed and fear run high. One can easily fall prey to these emotions and get involved in unfair practices. India has its fair share of such twisted practices, thanks to Harshad Mehta’s operations and the like.</p><p>This is where <strong>SEBI</strong> ensure that people adhere to these regulations and compliance thereby making the markets a level playing field for everyone.</p><div class="tip custom-block"><p class="custom-block-title">Key takeaways from this article</p><ol><li>The stock market is the place to go to if you want to transact in equities.</li><li>Stock markets exist electronically and can be accessed through a stockbroker.</li><li>There are many different kinds of market participants operating in the stock markets.</li><li>Every entity operating in the market has to be regulated, and they can operate only within the framework as prescribed by the regulator.</li><li>SEBI is the regulator of the securities market in India. They set the legal framework and regulate all entities interested in operating in the market.</li><li>Most importantly you need to remember that SEBI is aware of what you are doing and they can flag you down if you are up to something fishy in the markets!</li></ol></div><h2 id="video" tabindex="-1">Video <a class="header-anchor" href="#video" aria-label="Permalink to &quot;Video&quot;">​</a></h2>',59)),e[1]||(e[1]=t("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/_Txy7RdM9pE",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""},null,-1)),e[2]||(e[2]=t("p",null,"The above video explains this article in hindi language.",-1)),e[3]||(e[3]=t("h2",{id:"comments",tabindex:"-1"},[c("Comments "),t("a",{class:"header-anchor",href:"#comments","aria-label":'Permalink to "Comments"'},"​")],-1)),o(n,null,{default:d(()=>[o(r)]),_:1})])}const x=i(g,[["render",m]]);export{v as __pageData,x as default};
